!function(){function e(e){return function(e){if(Array.isArray(e))return t(e)}(e)||function(e){if("undefined"!=typeof Symbol&&null!=e[Symbol.iterator]||null!=e["@@iterator"])return Array.from(e)}(e)||function(e,r){if(e){if("string"==typeof e)return t(e,r);var a={}.toString.call(e).slice(8,-1);return"Object"===a&&e.constructor&&(a=e.constructor.name),"Map"===a||"Set"===a?Array.from(e):"Arguments"===a||/^(?:Ui|I)nt(?:8|16|32)(?:Clamped)?Array$/.test(a)?t(e,r):void 0}}(e)||function(){throw new TypeError("Invalid attempt to spread non-iterable instance.\nIn order to be iterable, non-array objects must have a [Symbol.iterator]() method.")}()}function t(e,t){(null==t||t>e.length)&&(t=e.length);for(var r=0,a=Array(t);r<t;r++)a[r]=e[r];return a}System.register(["./index-legacy-Bqiz6fhA.js"],function(t,r){"use strict";var a,o,s,l;return{setters:[function(e){a=e._,o=e.o,s=e.c,l=e.a}],execute:function(){var r={class:"max-w-4xl mx-auto p-6 bg-white text-gray-800 font-sans",itemscope:"",itemtype:"https://schema.org/Article"};t("default",a({},[["render",function(t,a){return o(),s("article",r,e(a[0]||(a[0]=[l('<meta itemprop="datePublished" content="2025-01-15"><meta itemprop="author" content="Tools321"><header><h2 id="jwt-heading" class="text-3xl font-bold mb-4 text-gray-900 text-center" itemprop="headline" aria-labelledby="jwt-heading">JWT解析器使用指南：Token 结构、时间字段与接口排查</h2></header><section class="bg-blue-50 rounded-xl border border-blue-200 p-5 mb-6" aria-labelledby="jwt-overview"><h3 id="jwt-overview" class="text-xl font-semibold text-blue-800 mb-3">什么是JWT解析器？</h3><p class="text-gray-700 leading-relaxed"><strong>JWT解析器</strong>是一款在线工具，能够将JWT（JSON Web Token）令牌拆解为Header、Payload和Signature三部分，解码并展示其中的<strong>用户信息、过期时间、签发者</strong>等关键数据。适用于接口调试、Token过期排查和登录问题诊断。 </p></section><p class="text-gray-600 mb-6 leading-relaxed"> 当接口返回401未授权、登录突然掉线或Token刷新失败时，第一步就是查看Token里的内容。JWT解析器让你无需写代码，粘贴Token即可快速查看其中的所有字段，判断是Token过期、时钟偏差还是刷新链路出了问题。 </p><section class="bg-gray-50 p-5 rounded-lg mb-6" aria-labelledby="jwt-knowledge"><h3 id="jwt-knowledge" class="text-xl font-semibold text-gray-800 mb-3">JWT的结构与字段</h3><p class="text-gray-700 mb-3"> JWT由三段Base64Url编码的字符串组成，用点号分隔： </p><ul class="space-y-2 text-gray-700"><li><strong>Header（头部）</strong>：包含令牌类型（typ）和签名算法（alg），如HS256、RS256</li><li><strong>Payload（载荷）</strong>：包含声明信息（JSON 格式，可用<a href="/dev/format-converter/" class="text-blue-600 hover:text-blue-700">JSON 格式化工具</a>美化），如用户ID（sub）、签发时间（iat）、过期时间（exp）</li><li><strong>Signature（签名）</strong>：用密钥对前两部分签名，确保数据未被篡改</li></ul><p class="mt-4 text-gray-600 text-sm"> 常见的Payload字段：iss（签发者）、sub（主题）、aud（受众）、exp（过期时间）、nbf（生效时间）、iat（签发时间）、jti（唯一标识，常由 <a href="/dev/uuid-generator/" class="text-blue-600 hover:text-blue-700">UUID 生成器</a> 产生）。 </p></section><section class="bg-blue-50 border-l-4 border-blue-400 p-5 rounded-r-lg mb-6" aria-labelledby="jwt-fields"><h3 id="jwt-fields" class="text-xl font-semibold text-gray-800 mb-4">关键时间字段解读</h3><div class="grid grid-cols-1 md:grid-cols-3 gap-4"><div class="bg-white p-4 rounded-lg shadow-sm"><h4 class="font-bold text-gray-800 mb-2">exp（过期时间）</h4><p class="text-sm text-gray-600">Token的失效时间戳，超过此时间后服务端应拒绝该Token</p></div><div class="bg-white p-4 rounded-lg shadow-sm"><h4 class="font-bold text-gray-800 mb-2">iat（签发时间）</h4><p class="text-sm text-gray-600">Token的创建时间戳，可用于计算Token的剩余有效期</p></div><div class="bg-white p-4 rounded-lg shadow-sm"><h4 class="font-bold text-gray-800 mb-2">nbf（生效时间）</h4><p class="text-sm text-gray-600">Token的最早生效时间，在此之前不应被接受</p></div></div></section><section class="bg-gray-50 p-5 rounded-lg mb-6" aria-labelledby="jwt-tutorial"><h3 id="jwt-tutorial" class="text-xl font-semibold text-gray-800 mb-3">使用步骤</h3><ol class="list-decimal pl-5 space-y-3 text-gray-700"><li>将完整的<strong>JWT Token</strong>粘贴到输入框中</li><li>工具自动拆分为Header、Payload、Signature三段</li><li>重点查看Payload中的<strong>exp、iat和nbf</strong>时间字段</li><li>对比当前时间（可用<a href="/dev/timestamp/" class="text-blue-600 hover:text-blue-700">时间戳转换工具</a>换算具体日期），判断Token是否过期或尚未生效</li><li>复制解码结果，方便与后端团队沟通问题</li></ol></section><section class="bg-amber-50 border-l-4 border-amber-400 p-5 rounded-r-lg mb-6" aria-labelledby="jwt-scenarios"><h3 id="jwt-scenarios" class="text-xl font-semibold text-gray-800 mb-3">典型应用场景</h3><ul class="space-y-3 text-gray-700"><li><strong>Token过期排查</strong>：接口返回401时，查看exp字段确认是否真的过期</li><li><strong>时钟偏差检测</strong>：对比iat和服务器时间，排查客户端时钟不准的问题</li><li><strong>刷新链路验证</strong>：检查refresh token的有效期和内容是否正确</li><li><strong>权限信息查看</strong>：解码Payload中的角色和权限字段，确认授权范围</li><li><strong>多服务联调</strong>：跨服务传递Token时，确认各服务解析结果一致</li></ul></section><section class="bg-gray-50 p-5 rounded-lg mb-6" aria-labelledby="jwt-principle"><h3 id="jwt-principle" class="text-xl font-semibold text-gray-800 mb-3">技术原理</h3><p class="text-gray-700 mb-3"> JWT的Header和Payload部分使用<strong>Base64Url编码</strong>，而非加密。这意味着任何人都可以解码查看内容，因此不要在JWT中存储敏感信息。数据的安全性由Signature保证——签名使用服务端密钥生成，篡改内容会导致签名验证失败。 </p><p class="text-gray-700"> 本工具在浏览器本地完成解码，不会将Token发送到任何服务器。但请注意：能解码不代表Token有效，Token的真实性需要通过服务端密钥验证签名来确认。 </p></section><section class="mb-6" aria-labelledby="jwt-faq"><h3 id="jwt-faq" class="text-xl font-semibold text-gray-800 mb-4">常见问题</h3><div class="space-y-3"><details class="border border-gray-200 rounded-lg p-4 hover:bg-gray-50 transition-colors" open><summary class="font-semibold cursor-pointer text-gray-800">能校验JWT签名吗？</summary><p class="text-gray-600 mt-2 pt-2 border-t border-gray-100">本工具主要做解码和查看，不负责用服务端密钥验证签名。签名验证需要密钥，出于安全考虑不应在前端暴露。如需验证签名，请在后端使用对应的JWT库。</p></details><details class="border border-gray-200 rounded-lg p-4 hover:bg-gray-50 transition-colors"><summary class="font-semibold cursor-pointer text-gray-800">能解码就代表Token可用吗？</summary><p class="text-gray-600 mt-2 pt-2 border-t border-gray-100">不代表。能解码只说明格式像JWT，是否有效还要看签名是否正确、是否在有效期内、签发者是否可信等。解码只是排查问题的第一步。</p></details><details class="border border-gray-200 rounded-lg p-4 hover:bg-gray-50 transition-colors"><summary class="font-semibold cursor-pointer text-gray-800">Token内容会上传吗？</summary><p class="text-gray-600 mt-2 pt-2 border-t border-gray-100">不会。当前页面在浏览器本地解析Token，不会将内容发送到任何服务器。适合做第一轮排查，但建议不要将生产环境的Token分享给他人。</p></details><details class="border border-gray-200 rounded-lg p-4 hover:bg-gray-50 transition-colors"><summary class="font-semibold cursor-pointer text-gray-800">JWT和Session有什么区别？</summary><p class="text-gray-600 mt-2 pt-2 border-t border-gray-100">JWT是无状态的，所有信息都存在Token中，服务端不需要存储会话数据；Session是有状态的，会话信息存储在服务端。JWT更适合分布式系统和微服务架构，但无法主动让单个Token失效。</p></details><details class="border border-gray-200 rounded-lg p-4 hover:bg-gray-50 transition-colors"><summary class="font-semibold cursor-pointer text-gray-800">为什么Token过期了但接口还能用？</summary><p class="text-gray-600 mt-2 pt-2 border-t border-gray-100">可能原因：1）客户端时钟与服务器时钟不一致；2）服务端对exp字段的校验有容差；3）使用了refresh token自动续期。建议先检查exp时间戳和当前时间的差异。</p></details><details class="border border-gray-200 rounded-lg p-4 hover:bg-gray-50 transition-colors"><summary class="font-semibold cursor-pointer text-gray-800">HS256和RS256有什么区别？</summary><p class="text-gray-600 mt-2 pt-2 border-t border-gray-100">HS256使用相同的密钥进行签名和验证（对称加密），RS256使用私钥签名、公钥验证（非对称加密）。RS256更安全，适合多服务场景，可配合<a href="/dev/encrypt-tool/" class="text-blue-600 hover:text-blue-700">加密工具</a>理解对称与非对称加密；HS256更简单，适合单服务场景。</p></details><details class="border border-gray-200 rounded-lg p-4 hover:bg-gray-50 transition-colors"><summary class="font-semibold cursor-pointer text-gray-800">Base64Url 和 Base64 有什么区别？</summary><p class="text-gray-600 mt-2 pt-2 border-t border-gray-100">Base64Url 是 Base64 的 URL 安全变体：它把标准 Base64 中的 <code>+</code> 替换为 <code>-</code>、<code>/</code> 替换为 <code>_</code>，并去掉末尾的 <code>=</code> 填充，避免这些字符在 URL、文件名或 Cookie 中引起解析错误。JWT 的 Header 和 Payload 正是用 Base64Url 编码，因此能直接放进 URL 参数中传输。</p></details></div></section><footer class="text-center text-gray-400 text-sm pt-4 border-t border-gray-200"><p>本文介绍了JWT解析器的功能、JWT结构和常见问题，帮助你快速解码Token排查接口授权问题。</p></footer>',12)])))}]]))}}})}();
